var lines = new List<PurchaseLine>
{
    new("Notebook", 2, 4.50m),
    new("Pen", 0, 1.25m),
    new("Folder", 3, 2m)
};

IEnumerable<decimal> activeTotals = lines
    .Where(line => line.Quantity > 0)
    .Select(line => line.Quantity * line.UnitPrice);

decimal orderTotal = activeTotals.Sum();
Console.WriteLine(orderTotal);

sealed record PurchaseLine(string Product, int Quantity, decimal UnitPrice);
